        "about": {
            "title": "ഞങ്ങളെക്കുറിച്ച്",
            "welcome": "ഞങ്ങളുടെ അപ്ലിക്കേഷനിലേക്ക് സ്വാഗതം, സുഗമമായ അനുഭവത്തിനുള്ള നിങ്ങളുടെ ആത്യന്തിക ലക്ഷ്യസ്ഥാനം! ഞങ്ങൾ നിങ്ങൾക്ക് മികച്ച സേവനങ്ങൾ, അസാധാരണമായ ഡീലുകൾ, അതുല്യമായ സൗകര്യം എന്നിവ നൽകാൻ രൂപകൽപ്പന ചെയ്ത ഒരു നൂതന, ഉപഭോക്തൃ-കേന്ദ്രീകൃത പ്ലാറ്റ്ഫോമാണ് — എല്ലാം നിങ്ങളുടെ വിരൽത്തുമ്പിൽ.",
            "storyTitle": "ഞങ്ങളുടെ കഥ",
            "storyP1": "ഞങ്ങൾ ഒരു ലളിതമായ ആശയത്തോടെ ആരംഭിച്ചു: വൈവിധ്യമാർന്ന സേവനങ്ങൾ നൽകുന്ന ഒരു പ്ലാറ്റ്ഫോം നൽകുക മാത്രമല്ല, മുഴുവൻ പ്രക്രിയയും എളുപ്പവും ആസ്വാദ്യകരവുമാക്കുക.",
            "storyP2": "വിനീതമായ തുടക്കത്തിൽ നിന്ന്, ഞങ്ങൾ വേഗത്തിൽ ഏറ്റവും വിശ്വസനീയമായ പ്ലാറ്റ്ഫോമുകളിലൊന്നായി വളർന്നു. ഉപഭോക്തൃ സംതൃപ്തി, പ്രവേശനക്ഷമത, നിരന്തരമായ നവീകരണം എന്നിവയുടെ ഞങ്ങളുടെ പ്രധാന മൂല്യങ്ങൾ ഞങ്ങളുടെ ഓഫറുകൾ വികസിപ്പിക്കാൻ ലക്ഷ്യമിടുമ്പോൾ ഞങ്ങളെ മുന്നോട്ട് നയിക്കുന്നു."
        },
